-- Runner copy of server/src/db-draft/0010_principal_isolation.sql.
-- Generated by scripts/build-tenant-migration.mjs; edit the draft and regenerate, do not hand-edit
-- both. Differences from the draft: psql meta-commands removed, and BEGIN/COMMIT removed because
-- the migration runner applies every file inside its own transaction (and records the result in
-- schema_migrations). Semantics are otherwise identical.

-- =============================================================================
-- DHAROHAR — DRAFT migration 0010: isolate officer rows from each other
--
-- Why this migration exists
--
--   Migrations 0006 and 0009 put LAND RECORDS under row-level security. The four tables that decide
--   WHO a caller is and WHAT their tenant controls were deliberately left outside it, and
--   docs/TENANT-DATA-ACCESS.md named that as the residual gap rather than arguing it away:
--
--     users                  59 officer rows, including password_hash and salt
--     user_jurisdictions     every officer's district postings
--     user_capabilities      every officer's elevated capabilities
--     organization_districts which tenant administers / audits / reads which district
--
--   The reason they were unscoped was real: authorization has to read these tables to DISCOVER the
--   tenant, so a policy keyed on a discovered value looks like a closed loop. But "we cannot scope it
--   by tenant" and "the runtime role may therefore read every organization's officers, their postings,
--   their capabilities and their password hashes" are different claims, and the second one was never
--   necessary. As `dharohar_app`, `SELECT * FROM users` returned all of it, with no context bound.
--
-- What this file does
--
--   1. ONE narrow identity lookup. `dharohar_officer_for_login(identifier)` is the only path in the
--      system that may find an account before the account is known — because signing in is exactly
--      that moment. It is owned by a NOLOGIN role (`dharohar_identity`) that holds BYPASSRLS solely so
--      that lookup can work, takes one exact identifier, and returns at most one row. There is no
--      function that lists, searches or counts principals.
--   2. Row-level security on all four tables, for `dharohar_app` only: a caller sees its own row and
--      the rows of the organization it belongs to. `loadPrincipal` binds the officer id from the
--      verified token first, reads its own row, and only then binds the organization — so the loop is
--      broken by ordering, not by an exception.
--   3. The credential columns taken away. `dharohar_app` keeps SELECT on `users` except
--      `password_hash` and `salt`. That is a column-level privilege, so it survives even though the
--      rows are now also row-scoped — the two controls are independent, and both are checked below.
--
-- What deliberately does NOT change
--
--   * The unowned account. An officer row with no organization is visible to NOBODY through the API:
--     the same fail-closed rule that already governs quarantined parcels. The roster's former
--     "no organization means you see every account" clause is removed in code with this migration, and
--     the disposition queue stays what it always was — an owner-side view, reachable by the one-shot
--     commands and by `dharohar_verifier`, both of which are exempt from row-level security.
--   * Anything a tenant may do inside its own tenant. Provisioning, roster, capability and jurisdiction
--     changes all keep working; they now run inside the caller's tenant transaction so that the
--     WITH CHECK clauses have an organization to check against.
--   * `districts` (shared geography) and `append_only_audit_logs` (chain verification is whole-table).
--
-- Running it
--
--   psql is used by the drill; the migration runner applies the derived copy of this file inside its
--   own transaction. Rollback: rollback-0010.sql.
-- =============================================================================


-- ---- 1. The identity role: cannot log in, owns nothing but the lookup --------
-- BYPASSRLS here is not a shortcut around the policy this file installs; it is what makes the one
-- pre-identity lookup possible at all. The mitigations that make it safe are narrow and testable: the
-- role has NOLOGIN (nothing can connect as it), NOINHERIT (no role membership to inherit privileges
-- through), it owns exactly the functions created below, and it is granted SELECT on `users` and
-- nothing else in the application schema.
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dharohar_identity') THEN
    ALTER ROLE dharohar_identity WITH NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE
      NOINHERIT BYPASSRLS NOREPLICATION CONNECTION LIMIT 0;
    RAISE NOTICE '[0010] role dharohar_identity already existed - attributes re-asserted';
  ELSE
    CREATE ROLE dharohar_identity NOLOGIN
      NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT BYPASSRLS NOREPLICATION
      CONNECTION LIMIT 0;
    RAISE NOTICE '[0010] created role dharohar_identity (no login, owns only the identity lookups)';
  END IF;
END
$do$;

GRANT USAGE ON SCHEMA public TO dharohar_identity;
-- The lookup needs the credential columns; nothing else does.
GRANT SELECT ON TABLE users TO dharohar_identity;

-- ---- 2. The one pre-identity lookup ----------------------------------------
-- `RETURNS SETOF users` on purpose: an explicit column list would be a second copy of the schema to
-- keep in sync, and a migration cannot know which columns a later release adds. SECURITY DEFINER with a
-- pinned search_path, so an invoker cannot redirect the body by setting search_path first.
CREATE OR REPLACE FUNCTION public.dharohar_officer_for_login(p_identifier text)
RETURNS SETOF public.users
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
  -- One exact identifier: an email, an officer id, or a badge number. Matched case-insensitively on
  -- all three because that is what the login path has always done — emails and badges lower-cased,
  -- officer ids upper-cased — and a login that depends on how the operator typed their own id is a
  -- defect, not a policy. No LIKE, no range: this is how you sign in, not how you enumerate. LIMIT 1
  -- because the lookup upstream has always taken the first match.
  SELECT * FROM public.users
   WHERE p_identifier IS NOT NULL
     AND btrim(p_identifier) <> ''
     AND (
           LOWER(btrim(email)) = LOWER(btrim(p_identifier))
        OR LOWER(btrim(id)) = LOWER(btrim(p_identifier))
        OR LOWER(btrim(badge_number)) = LOWER(btrim(p_identifier))
     )
   LIMIT 1
$fn$;

-- The startup warning "this production database has nobody who can sign in" needs a fact, not a
-- row set. A boolean leaks nothing; a count of another tenant's staff would.
CREATE OR REPLACE FUNCTION public.dharohar_has_any_officer()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
  SELECT EXISTS (SELECT 1 FROM public.users)
$fn$;

REVOKE ALL ON FUNCTION public.dharohar_officer_for_login(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.dharohar_has_any_officer() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.dharohar_officer_for_login(text) TO dharohar_app;
GRANT EXECUTE ON FUNCTION public.dharohar_has_any_officer() TO dharohar_app;
ALTER FUNCTION public.dharohar_officer_for_login(text) OWNER TO dharohar_identity;
ALTER FUNCTION public.dharohar_has_any_officer() OWNER TO dharohar_identity;

-- ---- 3. Row-level security on the four authorization tables ----------------
ALTER TABLE users                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_jurisdictions     ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_capabilities      ENABLE ROW LEVEL SECURITY;
ALTER TABLE organization_districts ENABLE ROW LEVEL SECURITY;

DO $do$
DECLARE
  t          text;
  cmd        text;
  body       text;
  check_body text;
BEGIN
  FOREACH t IN ARRAY ARRAY['users','user_jurisdictions','user_capabilities','organization_districts'] LOOP
    FOREACH cmd IN ARRAY ARRAY['select','insert','update','delete'] LOOP
      EXECUTE format('DROP POLICY IF EXISTS tenant_%s_%I ON %I', cmd, t, t);
    END LOOP;

    IF t = 'users' THEN
      -- Own row, or a row in the organization this session belongs to. Both GUCs unset: NULL, so
      -- neither arm is true and nothing is visible — an unbound connection sees no officers.
      body := $q$(id = current_setting('app.user_id', true)
               OR (organization_id IS NOT NULL
                   AND organization_id = current_setting('app.organization_id', true)))$q$;
      -- A new officer must land in the actor's tenant. Unowned rows stay creatable because that is
      -- the documented bootstrap case (an administrator created before any tenant exists) and an
      -- unowned row is visible to no one, so it cannot be used to reach another tenant's data.
      check_body := $q$(organization_id IS NULL
                     OR organization_id = current_setting('app.organization_id', true))$q$;
    ELSIF t IN ('user_jurisdictions','user_capabilities') THEN
      -- A grant row is readable when it belongs to a user this caller can already see. The subquery
      -- runs under `users`' own policy, so this cannot be used to step sideways.
      body := $q$(user_id = current_setting('app.user_id', true)
               OR user_id IN (SELECT u.id FROM users u
                               WHERE u.organization_id = current_setting('app.organization_id', true)))$q$;
      check_body := body;
    ELSE
      -- organization_districts IS the tenant's authority. Reading another tenant's grants would map
      -- the whole multi-tenant estate; writing one would be a takeover.
      body   := $q$(organization_id IS NOT NULL
                 AND organization_id = current_setting('app.organization_id', true))$q$;
      check_body := body;
    END IF;

    EXECUTE format('CREATE POLICY tenant_select_%I ON %I AS PERMISSIVE FOR SELECT TO dharohar_app USING %s', t, t, body);
    EXECUTE format('CREATE POLICY tenant_insert_%I ON %I AS PERMISSIVE FOR INSERT TO dharohar_app WITH CHECK %s', t, t, check_body);
    EXECUTE format('CREATE POLICY tenant_update_%I ON %I AS PERMISSIVE FOR UPDATE TO dharohar_app USING %s WITH CHECK %s', t, t, body, check_body);
    EXECUTE format('CREATE POLICY tenant_delete_%I ON %I AS PERMISSIVE FOR DELETE TO dharohar_app USING %s', t, t, body);
    RAISE NOTICE '[0010] % scoped to own row / own organization for 4 commands (role dharohar_app)', t;
  END LOOP;
END
$do$;

-- ---- 4. The credential columns, removed from the runtime role --------------
-- Row scope and column scope are different controls: even for a row this role may read, it must not
-- be able to read a password hash. Revoke the table-level SELECT and re-grant every column except the
-- two secrets. `SELECT *` on `users` now fails for this role by design; the code paths that used it
-- were migrated to the lookup function or to explicit column lists.
DO $do$
DECLARE
  cols   text;
  secret text[] := ARRAY['password_hash','salt'];
BEGIN
  SELECT string_agg(c.column_name, ', ' ORDER BY c.ordinal_position) INTO cols
    FROM information_schema.columns c
   WHERE c.table_schema = 'public' AND c.table_name = 'users'
     AND c.column_name <> ALL (secret);
  IF cols IS NULL OR cols = '' THEN
    RAISE EXCEPTION E'[PRINCIPAL_COLUMNS_UNEXPECTED] users has no non-secret columns to grant - the table is not what this migration expects. Nothing was changed.';
  END IF;

  EXECUTE 'REVOKE SELECT ON public.users FROM dharohar_app';
  EXECUTE format('GRANT SELECT (%s) ON public.users TO dharohar_app', cols);
  RAISE NOTICE '[0010] dharohar_app: SELECT on users limited to every column except password_hash and salt';
END
$do$;

-- ---- 5. Self-check: refuse to report success on a lockdown that is not real
-- Every assertion below has been wrong at least once in this project's history, in a different
-- context, while the code looked correct. A policy that parses, a grant that runs and a role that
-- exists are not the same as access being closed.
DO $do$
DECLARE
  problems text[] := ARRAY[]::text[];
  lockdown boolean;
BEGIN
  IF (SELECT count(*) FROM pg_policies
       WHERE tablename IN ('users','user_jurisdictions','user_capabilities','organization_districts')
         AND policyname LIKE 'tenant_%') <> 16 THEN
    problems := array_append(problems, 'expected 16 tenant policies on the four authorization tables');
  END IF;

  IF EXISTS (SELECT 1 FROM pg_policies
              WHERE tablename IN ('users','user_jurisdictions','user_capabilities','organization_districts')
                AND permissive <> 'PERMISSIVE') THEN
    problems := array_append(problems, 'a policy on an authorization table is not PERMISSIVE');
  END IF;

  IF EXISTS (SELECT 1 FROM pg_policies
              WHERE tablename IN ('users','user_jurisdictions','user_capabilities','organization_districts')
                AND roles <> ARRAY['dharohar_app']::name[]) THEN
    problems := array_append(problems, 'a policy applies to someone other than dharohar_app');
  END IF;

  IF EXISTS (SELECT 1 FROM (
              SELECT tablename, cmd FROM pg_policies
               WHERE tablename IN ('users','user_jurisdictions','user_capabilities','organization_districts')
               GROUP BY 1,2 HAVING count(*) > 1) dup) THEN
    -- Two PERMISSIVE policies on one command are OR-ed: a second "narrowing" policy would widen it.
    problems := array_append(problems, 'an authorization table has two policies for one command');
  END IF;

  -- The privilege half only means something on a database that scripts/roles.sql has already been
  -- applied to. The supported order is the opposite — compose runs `migrate` before `roleinit`, and
  -- `scripts/test-fresh-install.sh` migrates an empty database before it locks any role down — so on a
  -- new database dharohar_app holds nothing at all yet. That is the documented order, not a broken
  -- lockdown, and aborting here would make a fresh install impossible (found by running
  -- `npm run test:registry`, which builds throwaway databases exactly that way, on 2026-10-23).
  -- When the grants do exist, every invariant below is asserted; when they do not, roleinit is the
  -- step that creates them and `scripts/validate-stack.sh` is the gate that checks them.
  --
  -- has_any_column_privilege, not has_table_privilege: after the column split in section 4 the runtime
  -- role holds *no* table-level SELECT on users at all, so has_table_privilege answers false on a
  -- correctly locked-down database — measured 2026-10-23 (any_column=true, table=false). Using it as
  -- the discriminator would have deferred these assertions forever, which is the same as deleting them.
  --
  -- And not a users privilege at all: this migration grants column SELECT on users itself, in section 4,
  -- before this block runs. A predicate satisfied by the migration's own work is always true and tests
  -- nothing — that is how the abort reappeared on 2026-10-23 after the first fix. parcels SELECT comes
  -- only from roles.sql, which is precisely the state being asked about.
  lockdown := to_regclass('public.parcels') IS NOT NULL
          AND has_table_privilege('dharohar_app', 'public.parcels', 'SELECT');

  IF lockdown THEN
    IF has_column_privilege('dharohar_app', 'public.users', 'password_hash', 'SELECT') THEN
      problems := array_append(problems, 'dharohar_app can still SELECT users.password_hash');
    END IF;
    IF has_column_privilege('dharohar_app', 'public.users', 'salt', 'SELECT') THEN
      problems := array_append(problems, 'dharohar_app can still SELECT users.salt');
    END IF;
    IF NOT has_column_privilege('dharohar_app', 'public.users', 'organization_id', 'SELECT') THEN
      problems := array_append(problems, 'dharohar_app lost SELECT on a column the roster and policies need');
    END IF;
    -- UPDATE is deliberately still table-level: resetting a password writes exactly those two columns,
    -- and the new hash must be settable by the provisioning path.
    IF NOT has_table_privilege('dharohar_app', 'public.users', 'UPDATE') THEN
      problems := array_append(problems, 'provisioning can no longer UPDATE users at all');
    END IF;
    IF has_table_privilege('dharohar_app', 'public.users', 'DELETE') THEN
      problems := array_append(problems, 'roles.sql re-granted DELETE on users; an account must be retired, not removed');
    END IF;
  ELSE
    RAISE NOTICE '[0010] privilege invariants not asserted: scripts/roles.sql has not been applied to this database yet (dharohar_app holds no SELECT on users). roleinit applies them; validate-stack.sh checks them.';
  END IF;

  IF (SELECT rolcanlogin FROM pg_roles WHERE rolname = 'dharohar_identity') THEN
    problems := array_append(problems, 'dharohar_identity can log in - BYPASSRLS on a login-capable role is not acceptable');
  END IF;
  IF (SELECT rolsuper FROM pg_roles WHERE rolname = 'dharohar_identity') THEN
    problems := array_append(problems, 'dharohar_identity is a superuser');
  END IF;
  IF pg_has_role('dharohar_app', 'dharohar_identity', 'MEMBER') THEN
    problems := array_append(problems, 'dharohar_app is a member of dharohar_identity, which would hand it BYPASSRLS');
  END IF;
  IF NOT has_function_privilege('dharohar_app', 'dharohar_officer_for_login(text)', 'EXECUTE') THEN
    problems := array_append(problems, 'the login lookup is not executable by the runtime role - nobody could sign in');
  END IF;
  -- Checked through the ACL rather than has_function_privilege('PUBLIC', ...), which answers about the
  -- pseudo-role rather than about the grant. Anything other than the owner and the runtime role
  -- holding EXECUTE means some other identity can call a BYPASSRLS lookup.
  IF EXISTS (SELECT 1
               FROM pg_proc p, aclexplode(p.proacl) AS x
              WHERE p.pronamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')
                AND p.proname IN ('dharohar_officer_for_login','dharohar_has_any_officer')
                AND x.privilege_type = 'EXECUTE'
                AND x.grantee NOT IN (SELECT r.oid FROM pg_roles r
                                       WHERE r.rolname IN ('dharohar_app','dharohar_identity'))) THEN
    problems := array_append(problems, 'some role other than dharohar_app holds EXECUTE on the identity lookups');
  END IF;

  IF array_length(problems, 1) IS NOT NULL THEN
    RAISE EXCEPTION E'[PRINCIPAL_ISOLATION_INCOMPLETE] %\n  Nothing was changed on this run: the transaction is rolled back by the migration runner.', array_to_string(problems, '; ');
  END IF;
  RAISE NOTICE '[0010] self-check passed: 16 policies, identity role unable to log in, login lookup reachable by exactly one role, credential columns %',
    CASE WHEN lockdown THEN 'unreadable and provisioning still writable' ELSE 'invariants deferred to roleinit (no grants in this database yet)' END;
END
$do$;

-- ---- 6. Report --------------------------------------------------------------
DO $do$
BEGIN
  RAISE NOTICE '[0010] tables under row-level security now: %',
    (SELECT string_agg(c.relname, ', ' ORDER BY c.relname) FROM pg_class c
       JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.relrowsecurity AND n.nspname = 'public');
  RAISE NOTICE '[0010] NOTE: roles.sql must NOT re-grant table-level SELECT on users, or section 4 silently undoes itself on the next roleinit run.';
END
$do$;


-- End of 0010. rollback-0010.sql reverses it: policies dropped, security disabled, table-level SELECT
-- restored, functions and the identity role removed.
